import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const g=JSON.parse('{"title":"Folk","description":"","frontmatter":{},"headers":[],"relativePath":"demos/FOLK.md","filePath":"demos/FOLK.md"}'),o={name:"demos/FOLK.md"};function s(h,e,l,i,c,d){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="folk" tabindex="-1">Folk <a class="header-anchor" href="#folk" aria-label="Permalink to &quot;Folk&quot;">​</a></h1><p>The demo songs in the folk style. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#arrangement_shanty">Few Patterns</a>: <code>18_arrangement_shanty.yml</code></li><li><a href="#complex_gifts_chain">Chains</a>: <code>15_complex_gifts_chain.yml</code></li><li><a href="#hocket_shanty">Hocketing</a>: <code>17_hocket_shanty.yml</code></li></ul><p><a id="arrangement_shanty"></a></p><h2 id="few-patterns-18-arrangement-shanty-yml" tabindex="-1">Few Patterns: <code>18_arrangement_shanty.yml</code> <a class="header-anchor" href="#few-patterns-18-arrangement-shanty-yml" aria-label="Permalink to &quot;Few Patterns: `18_arrangement_shanty.yml`&quot;">​</a></h2><p>The Wellerman again, with eight parts built from only four note patterns. The harmony is the melody patterns transposed on its track, the bass grabs the roots of the pad&#39;s chords, and a counter-line grabs the melody in its own rhythm. Read this one to see how to set up a song so that changing one pattern changes every part that follows it.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/18_arrangement_shanty.yml" target="_blank" rel="noreferrer"><code>examples/learning/18_arrangement_shanty.yml</code></a> · A minor · 100 BPM · 2:34 · 8 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">grabs</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/ARPEGGIATOR">✓</a></td><td style="text-align:center;"><a href="./../CLIPS#grabbing-notes">✓</a></td></tr></tbody></table><p><a id="complex_gifts_chain"></a></p><h2 id="chains-15-complex-gifts-chain-yml" tabindex="-1">Chains: <code>15_complex_gifts_chain.yml</code> <a class="header-anchor" href="#chains-15-complex-gifts-chain-yml" aria-label="Permalink to &quot;Chains: `15_complex_gifts_chain.yml`&quot;">​</a></h2><p>Simple Gifts on a single track, growing from the plain tune into triads, then synthwave, then happy metal, using a few patterns and a chain for each scene. The demo shows that a chain runs its steps in order, each working on what the one before made.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/15_complex_gifts_chain.yml" target="_blank" rel="noreferrer"><code>examples/learning/15_complex_gifts_chain.yml</code></a> · A major · 120 BPM · 2:24 · 9 scenes · 1 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">ratchets</th><th style="text-align:center;">chains</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/ARPEGGIATOR">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#advanced">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td></tr></tbody></table><p><a id="hocket_shanty"></a></p><h2 id="hocketing-17-hocket-shanty-yml" tabindex="-1">Hocketing: <code>17_hocket_shanty.yml</code> <a class="header-anchor" href="#hocketing-17-hocket-shanty-yml" aria-label="Permalink to &quot;Hocketing: `17_hocket_shanty.yml`&quot;">​</a></h2><p>The Wellerman, held by a muted track called SILENT melody, with up to four voices taking turns at its notes, one note each, through a Hocket generator that names the melody&#39;s track as its source. That&#39;s called hocketing. One voice plays every note, two alternate, and four each play every fourth note; each voice has a sound of its own, flute, clarinet, oboe and violin, to hear the tune pass between them.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/17_hocket_shanty.yml" target="_blank" rel="noreferrer"><code>examples/learning/17_hocket_shanty.yml</code></a> · A minor · 100 BPM · 2:14 · 7 scenes · 5 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chains</th><th style="text-align:center;">hocket</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../generators/HOCKET">✓</a></td></tr></tbody></table>',18)])])}const y=t(o,[["render",s]]);export{g as __pageData,y as default};
